{
  "name": "playformosa",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "node scripts/build.mjs",
    "test": "node --test tests/*.test.mjs tests/long-jump/*.test.mjs tests/hurdles/*.test.mjs tests/reaction-rod/*.test.mjs tests/fast-hands/*.test.mjs tests/high-jump/*.test.mjs tests/courtesy-contest/*.test.mjs",
