// Best-effort recorded starts; never awaited by gameplay, no offline queue or heartbeat.
export async function recordPlayStart(win,game){
 try{
 if(!['long-jump','hurdles','courtesy-contest','pole-vault','shot-put','discus','sprint-100m','run-400m','run-1500m','javelin','beer-slide','tower-climb'].includes(game))return;
 const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;let deviceId;
 try{deviceId=win.localStorage.getItem('pf-leaderboard-device-v1')}catch{}
 if(!uuid.test(deviceId||'')){deviceId=win.crypto.randomUUID();try{win.localStorage.setItem('pf-leaderboard-device-v1',deviceId)}catch{}}
 const body=JSON.stringify({game,deviceId,runId:win.crypto.randomUUID(),startedAt:Date.now()});
 for(let attempt=0;attempt<2;attempt++){
 const controller=new win.AbortController(),timer=win.setTimeout(()=>controller.abort(),5000);let retry=false;
 try{const response=await win.fetch('/api/play-counts/starts',{method:'POST',headers:{'Content-Type':'application/json'},body,signal:controller.signal});retry=response.status===429||response.status===503;}catch{retry=true}finally{win.clearTimeout(timer)}
 if(!retry||attempt===1)return;
 await new Promise(resolve=>win.setTimeout(resolve,2500));
 }
 }catch{} // Storage/crypto/runtime failures must not interrupt a round.
}

import {cp,mkdir,rm,writeFile,readFile} from 'node:fs/promises';
import {assertReleasedGames,assertProductionInventory} from './release-policy.mjs';
import {catalog} from '../src/catalog.mjs';
import {renderPage} from '../src/render.mjs';
const root = new URL('../',import.meta.url);
await assertReleasedGames(new URL('public/',root));
const highJump=JSON.parse(await readFile(new URL('../docs/high-jump-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));
const release=JSON.parse(await readFile(new URL('docs/hurdles-main/SOURCE-MANIFEST.json',root),'utf8'));
const rod=JSON.parse(await readFile(new URL('docs/reaction-rod-main/SOURCE-MANIFEST.json',root),'utf8'));
const studio=JSON.parse(await readFile(new URL('docs/studio-main/SOURCE-MANIFEST.json',root),'utf8'));
const jump=JSON.parse(await readFile(new URL('docs/long-jump-main/SOURCE-MANIFEST.json',root),'utf8'));
const fastHands=JSON.parse(await readFile(new URL('docs/fast-hands-main/SOURCE-MANIFEST.json',root),'utf8'));
const polish=JSON.parse(await readFile(new URL('docs/fast-hands-polish/SOURCE-MANIFEST.json',root),'utf8'));
const gestures=JSON.parse(await readFile(new URL('docs/mobile-gestures/SOURCE-MANIFEST.json',root),'utf8'));
const completedIcons=JSON.parse(await readFile(new URL('docs/app-icons-completion/MANIFEST.json',root),'utf8'));
const courtesy=JSON.parse(await readFile(new URL('docs/main-courtesy-help/MANIFEST.json',root),'utf8'));
const expansion=JSON.parse(await readFile(new URL('docs/main-expansion/ADMISSION.json',root),'utf8'));
const allowedPublicPaths=[...expansion.addedPublicPaths,...completedIcons.addedPublicPaths,...courtesy.addedPublicPaths,...release.allowedPublicPaths,...rod.addedPublicPaths,...studio.addedPublicPaths,...jump.addedPublicPaths,...fastHands.addedPublicPaths,...polish.addedPublicPaths,...gestures.addedPublicPaths,...highJump.addedPublicPaths];
await assertProductionInventory(new URL('public/',root),allowedPublicPaths);
const html=renderPage(catalog);
await writeFile(new URL('public/index.html',root),html);
await rm(new URL('dist/',root),{recursive:true,force:true});
await mkdir(new URL('dist/',root),{recursive:true});
await cp(new URL('public/',root),new URL('dist/',root),{recursive:true});
await assertReleasedGames(new URL('dist/',root));
await assertProductionInventory(new URL('dist/',root),allowedPublicPaths);
console.log('Built static Playformosa to dist/');

import {readdir,stat} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
export const releasedGameIds=['long-jump','hurdles','reaction-rod','fast-hands','fast-hands-catch','fast-hands-duel','high-jump','courtesy-contest','pole-vault','shot-put','discus','sprint-100m','run-400m','run-1500m','javelin','beer-slide','tower-climb'];
const releasedHtml=['long-jump/index.html','hurdles/index.html','reaction-rod/index.html','fast-hands/index.html','fast-hands/catch.html','fast-hands/duel.html','high-jump/index.html','courtesy-contest/index.html','pole-vault/index.html','shot-put/index.html','discus/index.html','sprint-100m/index.html','run-400m/index.html','run-1500m/index.html','javelin/index.html','beer-slide/index.html','tower-climb/index.html'];
// Production artifact admission, not merely homepage visibility.
export async function assertReleasedGames(root){
  root=root instanceof URL?fileURLToPath(root):root;
  const dir=path.join(root,'games');
  for(const e of await readdir(dir,{withFileTypes:true})){
    if(!e.isDirectory()||!['long-jump','hurdles','reaction-rod','fast-hands','shared','javelin','high-jump','courtesy-contest','pole-vault','shot-put','discus','sprint-100m','run-400m','run-1500m','beer-slide','tower-climb'].includes(e.name))throw Error('Unapproved game directory: '+e.name);
  }
  for(const entry of releasedHtml)await stat(path.join(dir,entry));
  const walk=async p=>{for(const e of await readdir(p,{withFileTypes:true})){
    const full=path.join(p,e.name),relative=path.relative(dir,full).split(path.sep).join('/');
    if(e.isDirectory())await walk(full);
    else if(e.name.endsWith('.html')&&!releasedHtml.includes(relative)&&!['shared/sports-credits.html','pole-vault/height-sources.html','shot-put/credits.html'].includes(relative))throw Error('Unapproved game HTML: '+relative);
  }};
  await walk(dir);
  return releasedGameIds;
}

export async function assertProductionInventory(root,allowedPaths){root=root instanceof URL?fileURLToPath(root):root;const seen=[];async function walk(p){for(const e of await readdir(p,{withFileTypes:true})){const full=path.join(p,e.name);if(e.isDirectory())await walk(full);else seen.push(path.relative(root,full).split(path.sep).join('/'));}}await walk(root);const allowed=new Set(allowedPaths);for(const p of seen)if(!allowed.has(p))throw Error('Unapproved production file: '+p);for(const p of allowed)if(!seen.includes(p))throw Error('Missing production file: '+p);return seen;}

import {readFile,readdir,stat} from 'node:fs/promises';
import{assertReleasedGames,assertProductionInventory}from'./release-policy.mjs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../dist/',import.meta.url));
async function files(dir){const entries=await readdir(dir,{withFileTypes:true});return (await Promise.all(entries.map(item=>item.isDirectory()?files(path.join(dir,item.name)):path.join(dir,item.name)))).flat();}
await assertReleasedGames(root);
const completedIcons=JSON.parse(await readFile(new URL('../docs/app-icons-completion/MANIFEST.json',import.meta.url),'utf8'));
const courtesy=JSON.parse(await readFile(new URL('../docs/main-courtesy-help/MANIFEST.json',import.meta.url),'utf8'));
const highJump=JSON.parse(await readFile(new URL('../docs/high-jump-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));
const release=JSON.parse(await readFile(new URL('../docs/hurdles-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const rod=JSON.parse(await readFile(new URL('../docs/reaction-rod-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const studio=JSON.parse(await readFile(new URL('../docs/studio-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const jump=JSON.parse(await readFile(new URL('../docs/long-jump-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const fastHands=JSON.parse(await readFile(new URL('../docs/fast-hands-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const polish=JSON.parse(await readFile(new URL('../docs/fast-hands-polish/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const gestures=JSON.parse(await readFile(new URL('../docs/mobile-gestures/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const expansion=JSON.parse(await readFile(new URL('../docs/main-expansion/ADMISSION.json',import.meta.url),'utf8'));await assertProductionInventory(root,[...expansion.addedPublicPaths,...completedIcons.addedPublicPaths,...courtesy.addedPublicPaths,...release.allowedPublicPaths,...rod.addedPublicPaths,...studio.addedPublicPaths,...jump.addedPublicPaths,...fastHands.addedPublicPaths,...polish.addedPublicPaths,...gestures.addedPublicPaths,...highJump.addedPublicPaths]);
const paths=await files(root);
let checked=0;
for(const file of paths){
  if(!/\.(html|mjs|css)$/.test(file))continue;
  const source=await readFile(file,'utf8');
  const refs=file.endsWith('.html')?[...source.matchAll(/(?:src|href)="([^"]+)"/g)].map(m=>m[1]):file.endsWith('.mjs')?[...source.matchAll(/(?:from\s*|import\s*)['"](\.[^'"]+)['"]/g)].map(m=>m[1]):[...source.matchAll(/url\(['"]?([^)'"\s]+)['"]?\)/g)].map(m=>m[1]);
  for(const ref of refs){
    if(/^(?:https?:|data:|blob:|mailto:)/.test(ref))continue;
    // Fixed server-side navigation routes are checked by homepage-portals.test.mjs.
    if(['taiwanfighter','taiwankart','soul10power','arcadeplatform'].some(id=>ref==='/api/play-counts/entries/'+id)&&path.relative(root,file)==='index.html'){checked++;continue;}
    if(ref==='#'){checked++;continue;}
    if(ref.startsWith('#')){assert.ok(new RegExp(`id=["']${ref.slice(1)}["']`).test(source),`Missing anchor ${ref} in ${file}`);checked++;continue;}
    let target=ref.startsWith('/')?path.join(root,ref):path.resolve(path.dirname(file),ref);
    target=target.split(/[?#]/)[0];
    let info;try{info=await stat(target);}catch{throw new Error(`Missing local reference ${ref} from ${path.relative(root,file)}`);}
    if(info.isDirectory())await stat(path.join(target,'index.html'));
    checked++;
  }
}
console.log(`Verified ${checked} local references across ${paths.length} output files. Browser visual/touch QA not performed.`);

const filterReleased=(entries=[])=>entries.filter(e=>e.release?.production===true);
const escape = value => String(value).replace(/[&<>"']/g, char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function validateExternalCatalog(releasedExternal){
  const approvedExternal={taiwanfighter:['https://taiwanfighter.playformosa.workers.dev/','/assets/portal-taiwanfighter.webp','/assets/portal-taiwanfighter-logo.webp'],soul10power:['https://soul10power.vercel.app/','/assets/portal-soul10power.webp'],taiwankart:['https://taiwankart.playformosa.workers.dev/','/assets/portal-taiwankart.webp'],arcadeplatform:['https://arcadeplatform.playformosa.workers.dev/']};
  const externalIds=new Set();
  for(const e of releasedExternal){const allowed=approvedExternal[e.id];if(!allowed||externalIds.has(e.id)||e.href!==allowed[0]||e.image!==allowed[1]||e.logo!==allowed[2])throw new Error('Unapproved external destination or asset');externalIds.add(e.id);}
}
const portalArrow='<svg class="portal-arrow" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M5 15 15 5M5 5h10v10"/></svg>';
const externalLink=(entry,label)=>`<a class="button portal-cta" href="${escape('/api/play-counts/entries/'+entry.id)}" target="_blank" rel="noopener noreferrer" aria-label="${escape(label)}：${escape(entry.title)}（另開新分頁）">${escape(label)} ${portalArrow}</a>`;
const renderEntryCount=entry=>`<p class="play-count" title="本功能啟用後，從平台點擊進入的累計次數；不是遊戲內開局次數" data-play-count="${escape(entry.id)}" aria-live="polite">開玩次數讀取中…</p>`;
function renderExternalGame(entry) {
 return `<article class="portal-card portal-card--${escape(entry.id)}" data-external-id="${escape(entry.id)}"><div class="portal-art"><img src="${escape(entry.image)}" alt="" width="1672" height="941" loading="lazy" decoding="async">${entry.logo?`<img class="portal-game-logo" src="${escape(entry.logo)}" alt="" width="1446" height="1120" loading="lazy" decoding="async">`:''}<span class="portal-art-label">${escape(entry.eyebrow)}</span></div><div class="portal-card-body"><p class="portal-genre">${escape(entry.genre)}</p><h3>${escape(entry.title)}</h3><p class="portal-description">${escape(entry.description)}</p>${renderEntryCount(entry)}<div class="portal-card-bottom"><span class="portal-destination">獨立遊戲網站</span>${externalLink(entry,'前往遊玩')}</div></div></article>`;
}
function renderPlatform(entry) {
 return `<article class="platform-feature" data-external-id="${escape(entry.id)}"><div class="platform-brand"><p class="portal-genre">${escape(entry.brand)} · 小遊戲平台</p><h3>${escape(entry.title)}</h3><span class="platform-brand-line" aria-hidden="true"></span></div><div class="platform-copy"><p>${escape(entry.description)}</p>${renderEntryCount(entry)}<div class="platform-actions">${externalLink(entry,'前往遊戲平台')}<span class="portal-destination">獨立平台・另開新分頁</span></div></div></article>`;
}
export function renderPage({games,events,minigames=[],externalGames=[],platforms=[]}) {
  const channel='production';
  const releasedGames=filterReleased(externalGames,channel),releasedPlatforms=filterReleased(platforms,channel);
  validateExternalCatalog([...releasedGames,...releasedPlatforms]);
  const externalSections=`${releasedGames.length?`<section class="portal-section" id="big-games" aria-labelledby="big-games-title"><div class="portal-section-heading"><div><p class="eyebrow">INDEPENDENT WORLDS</p><h2 id="big-games-title">大遊戲</h2></div><p class="portal-section-note">${releasedGames.length} 個世界，各自精彩。</p></div><p class="portal-intro">從山海江湖到島嶼街頭，選一個世界，展開你的旅程。</p><p class="portal-external-note">以下遊戲將在新分頁開啟，保留各自的遊戲介面。</p><div class="portal-grid">${releasedGames.map(renderExternalGame).join('')}</div></section>`:''}${releasedPlatforms.length?`<section class="portal-section platform-section" id="platforms" aria-labelledby="platforms-title"><div class="portal-section-heading"><div><p class="eyebrow">MORE WAYS TO PLAY</p><h2 id="platforms-title">還想再玩一款？</h2></div></div>${releasedPlatforms.map(renderPlatform).join('')}</section>`:''}`;
  const available=games.filter(game=>game.status==='available');
  const availableMinigames=minigames.filter(game=>game.status==='available');
  const approvedAthletics={'long-jump':undefined,hurdles:'/assets/hurdles-card.png','high-jump':'/assets/high-jump-card.png','pole-vault':'/assets/pole-vault-card.png','shot-put':'/assets/shot-put-card.png',discus:'/assets/discus-card.png','sprint-100m':'/assets/sprint-100m-card.png','run-400m':'/assets/run-400m-card.png','run-1500m':'/assets/run-1500m-card.png',javelin:'/assets/javelin-card.png'};
  for(const game of available)if(!Object.hasOwn(approvedAthletics,game.id)||game.href!==`/games/${game.id}/`||game.image!==approvedAthletics[game.id])throw new Error('Unapproved athletics route or card image');
  const approvedMinigames={
    'beer-slide':['/games/beer-slide/','/assets/beer-slide-card-v2.webp'],
    'tower-climb':['/games/tower-climb/','/assets/tower-climb-card.png'],
    'courtesy-contest':['/games/courtesy-contest/','/assets/courtesy-contest-card.jpg'],
    'reaction-rod':['/games/reaction-rod/','/assets/reaction-rod-card.png'],
    'fast-hands':['/games/fast-hands/?intro=1','/assets/fast-hands-card-v2.webp'],
    'fast-hands-catch':['/games/fast-hands/catch.html?intro=1','/games/fast-hands/assets/intro-catch-generated.webp'],
    'fast-hands-duel':['/games/fast-hands/duel.html?intro=1','/games/fast-hands/assets/intro-duel-generated.webp']
  };
  for(const game of availableMinigames){const approved=approvedMinigames[game.id];if(!approved||game.href!==approved[0]||game.image!==approved[1])throw new Error('Unapproved minigame');}
  const nextEvents=events.filter(event=>!available.some(game=>game.event===event));
  const featured=available[0];
  const renderCard=(game,collection)=>`<article class="game-card"><a href="${escape(game.href)}" class="game-thumbnail" tabindex="-1" aria-hidden="true"><img src="${escape(game.image || "/assets/hero-long-jump.png")}"${game.image ? (game.imageStyle==='illustration' ? ' class="game-illustration"' : ' class="game-scene"') : ''} alt="" width="1536" height="1024" loading="lazy"><span>${escape(collection)} · ${escape(game.event)}</span></a><div class="game-info"><p class="game-kicker">${escape(game.kicker || "第一個挑戰，先落地再說。")}</p><h3>${escape(game.title)}</h3><p class="event-label">${escape(game.event)}${game.label ? ` · ${escape(game.label)}` : ""}</p><p class="input-chip"><span aria-hidden="true">⌨ / ☝</span> ${escape(game.input || "鍵盤／觸控")}</p>${['long-jump','hurdles','high-jump','pole-vault','shot-put','discus','sprint-100m','run-400m','run-1500m','javelin','reaction-rod','beer-slide','tower-climb','fast-hands','fast-hands-catch','fast-hands-duel','courtesy-contest'].includes(game.id)?`<p class="play-count" title="本功能啟用後累計的開局紀錄" data-play-count="${escape(game.id)}" aria-live="polite">開玩次數讀取中…</p>`:''}</div><a class="button button-primary game-cta" href="${escape(game.href)}" aria-label="開始挑戰：${escape(game.title)}">開始挑戰 <span aria-hidden="true">↗</span></a></article>`;
  return `<!doctype html>
<html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fff8e9"><meta name="description" content="島遊無界的小遊戲實驗場。操作不一定專業，跌倒一定精彩。從四肢各有想法開始，挑戰不太正經的十項全能。"><title>島遊無界 PLAYFORMOSA｜小遊戲實驗場</title><link rel="stylesheet" href="/assets/home.css"><link rel="icon" type="image/png" sizes="32x32" href="./assets/app-icons/platform/favicon-32.png"><link rel="icon" type="image/png" sizes="48x48" href="./assets/app-icons/platform/favicon-48.png"><link rel="apple-touch-icon" sizes="180x180" href="./assets/app-icons/platform/apple-touch-icon.png"><link rel="manifest" href="./manifest.webmanifest"><meta name="application-name" content="島遊無界"><meta name="apple-mobile-web-app-title" content="島遊無界"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes"></head>
<body data-catalog-channel="${channel}"${releasedGames.length||releasedPlatforms.length?' class="has-portal"':''}><a class="skip-link" href="#main">跳到主要內容</a>
<div class="page-shell"><header class="site-header"><a class="wordmark" href="/" aria-label="島遊無界 PLAYFORMOSA 首頁"><span>島遊無界</span><small>PLAYFORMOSA</small></a><nav aria-label="主要導覽"><a href="#minigames">小遊戲</a><a href="#decathlon">十項全能</a>${releasedGames.length?'<a href="#big-games">大遊戲</a>':''}${releasedPlatforms.length?'<a href="#platforms">play. one more.</a>':''}<a href="#about">關於</a></nav></header>
<main id="main"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">小遊戲，大失控。</p><h1 id="hero-title">操作不一定<span class="underline orange">專業</span>，<br>跌倒一定<span class="underline teal">精彩</span>。</h1><p class="hero-subtitle">島遊無界的小遊戲實驗場</p><div class="hero-actions">${featured ? `<a class="button button-primary" href="${escape(featured.href)}">先跳一場 <span aria-hidden="true">↗</span></a>` : ''}<a class="button button-secondary" href="#games">逛逛遊戲 <span aria-hidden="true">↓</span></a></div></div><div class="hero-art"><div class="art-halo" aria-hidden="true"></div><img src="/assets/hero-long-jump.png" alt="一位手腳各自亂飛的逗趣跳遠選手" width="1536" height="1024" fetchpriority="high"><span class="comic-sticker" aria-hidden="true">四肢各有想法！</span><span class="hero-caption">認真起跳，隨緣著陸。</span></div></section>
<section class="series" id="decathlon" aria-labelledby="series-title"><div class="series-heading"><div><p class="eyebrow">THE VERY UNPROFESSIONAL GAMES</p><h2 id="series-title">十項全能挑戰</h2></div><p class="progress">目前開放 <strong>${available.length}<span> / ${events.length}</span></strong> 項</p></div><div class="series-body"><div id="games" class="game-list">${available.map(game=>renderCard(game,'十項全能')).join('')}</div>${nextEvents.length?`<details class="roadmap"><summary>查看後續項目 <span aria-hidden="true">＋</span></summary><div class="roadmap-content"><p>還有 ${nextEvents.length} 個項目正在暖身。先把這一跳玩明白！</p><ul>${nextEvents.map(event=>`<li><span>${escape(event)}</span><small>尚未開放</small></li>`).join('')}</ul><p class="roadmap-note">後續項目為開發規劃，開放時間未定。</p></div></details>`:''}</div></section>
<section class="series minigames" id="minigames" aria-labelledby="minigames-title"><div class="series-heading"><div><p class="eyebrow">SMALL GAMES, BIG REACTIONS</p><h2 id="minigames-title">小遊戲</h2></div><p class="progress">目前開放 <strong>${availableMinigames.length}</strong> 款</p></div><div class="series-body"><div class="game-list">${availableMinigames.map(game=>renderCard(game,'小遊戲')).join('')}${availableMinigames.length ? '' : '<p class="minigames-empty">更多怪點子，慢慢登場。</p>'}</div></div></section>
${externalSections}
<section id="about" class="about" aria-labelledby="about-title"><h2 id="about-title">島遊無界工作室 <span>| PLAYFORMOSA STUDIO</span></h2><p>我們把奇怪的點子，做成真的能玩的遊戲。</p></section></main><footer><span>MADE FOR A LITTLE FUN.</span><span class="home-count" data-home-count title="本功能啟用後累計；同一瀏覽器短時間重訪不重複計入" aria-live="polite">瀏覽次數讀取中…</span><a href="#main">回到上方 ↑</a></footer></div><script type="module" src="/assets/play-counts.mjs"></script></body></html>`;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {JSDOM} from 'jsdom';
import worker, {handleRequest} from '../worker/leaderboard/index.mjs';
